flags.typeql:
match
$m isa movie, has released $r, has tagline "Speed has no limits";
$r >= 2005;
$r <= 2010;
fetch {
  "title": $m.title
};

with fun max_votes() -> integer:
    match $m isa movie, has votes $v;
    return max($v);
match
    $m isa movie, has votes $v;
    let $max = max_votes();
    $v == $max;
    reviewed (reviewer: $p, film: $m);
    $p has name $n;
fetch {
    "name": $n
};

match
$p isa person;
$rel isa reviewed (reviewer: $p, film: $m);
$rel has summary "Silly, but fun";
limit 3;
fetch {
  "name": $p.name
};

match
$m isa movie, has votes $v;
reduce $max_votes = max($v);
match
$m2 isa movie, has votes $v2;
$v2 == $max_votes;
$rel isa acted_in (actor: $p, film: $m2), has roles $r;
$p has name $n;
fetch {
  "actor": $n,
  "roles": $r
};

match $p isa person, has born $b;
reduce $min_born = min($b);
match $p2 isa person, has born $b2;
$b2 == $min_born;
acted_in (actor: $p2, film: $m);
$m has votes $v;
sort $v desc;
limit 5;
fetch { "title": $m.title, "votes": $v, "released": $m.released };

match
$m isa movie, has tagline "Speed has no limits";
acted_in (actor: $p, film: $m);
$p has name $n;
limit 3;
fetch { "name": $n };

match
$laurence isa person, has name "Laurence Fishburne";
follows (follower: $laurence, followed: $followed);
follows (follower: $follower, followed: $laurence);
limit 5;
fetch {
  "FollowedByLaurence": $followed.name,
  "FollowsLaurence": $follower.name
};

match
$p isa person;
$m isa movie, has released $r;
$r < 1990;
$rel isa acted_in (actor: $p, film: $m), has roles $role;
reduce $totalRoles = count($role) groupby $p;
sort $totalRoles desc;
limit 3;
fetch {
  "actor": $p.name,
  "totalRoles": $totalRoles
};

match
$actor isa person;
acted_in (actor: $actor);
follows (followed: $actor, follower: $follower);
reduce $count = count($follower) groupby $actor;
sort $count desc;
limit 3;
fetch { "actorName": $actor.name, "followerCount": $count };

with fun min_born() -> integer:
  match $p isa person, has born $b;
  return min($b);
match
$p isa person, has born $b;
let $min = min_born();
$b == $min;
acted_in (actor: $p, film: $m);
fetch { "MovieTitle": $m.title };

match
$m isa movie, has tagline "Speed has no limits";
$p isa person;
produced (producer: $p, film: $m);
fetch {
  "movie": $m.title,
  "producer": $p.name
};

match
$m isa movie, has released $r, has votes $v;
$r >= 2000;
$r < 2010;
$p isa person;
$rel isa $t ($p, film: $m);
{ $t label directed; } or { $t label produced; };
sort $v desc;
limit 5;
fetch {
  "title": $m.title,
  "released": $r,
  "votes": $v
};

match
$m isa movie;
$rev isa reviewed (reviewer: $p, film: $m);
$rev has rating $rating;
reduce $sum = sum($rating), $count = count groupby $m;
match
let $avg = $sum / $count;
sort $avg asc;
limit 5;
fetch {
  "movie": $m.title,
  "average_rating": $avg
};

match
$m isa movie, has votes $v;
reduce $max_votes = max($v);
match
$m2 isa movie, has votes $v2;
$v2 == $max_votes;
acted_in (actor: $p, film: $m2);
$p has name $n;
fetch {
  "actor_name": $n
};

match
$p isa person;
acted_in (actor: $p, film: $m1);
directed (director: $p, film: $m2);
produced (producer: $p, film: $m3);
limit 3;
fetch {
  "name": $p.name
};

match
$p isa person, has born $b;
reduce $min_born = min($b);
match
$p2 isa person, has born $b2;
$b2 == $min_born;
acted_in (actor: $p2, film: $m);
$m has title $t;
fetch { "MovieTitle": $t };

match
$p isa person;
$m isa movie, has released $r;
$r < 1985;
$a isa acted_in (actor: $p, film: $m), has roles $role;
reduce $totalRoles = count($role) groupby $p;
sort $totalRoles desc;
limit 1;
fetch {
  "person": $p.name,
  "totalRoles": $totalRoles
};

match
  $p isa person;
  $m isa movie;
  reviewed (reviewer: $p, film: $m);
  produced (producer: $p, film: $m);
limit 3;
fetch {
  "personName": $p.name,
  "movieTitle": $m.title
};

match
$p isa person;
$m isa movie;
acted_in (actor: $p, film: $m);
directed (director: $p, film: $m);
produced (producer: $p, film: $m);
select $p;
distinct;
limit 3;
fetch { "personName": $p.name };

match
$p isa person;
$rel isa acted_in (actor: $p, film: $m);
$rel has roles $r;
reduce $totalRoles = count($r) groupby $p;
sort $totalRoles desc;
limit 3;
fetch {
  "name": $p.name,
  "totalRoles": $totalRoles
};

match
$p isa person;
$rel isa acted_in (actor: $p, film: $m);
$rel has roles $r;
reduce $totalRoles = count($r) groupby $p;
sort $totalRoles desc;
limit 3;
fetch { "name": $p.name, "totalRoles": $totalRoles };

match
  $p1 isa person, has name $n1;
  $p2 isa person, has name $n2;
  follows (follower: $p1, followed: $p2);
  follows (follower: $p2, followed: $p1);
limit 3;
fetch {
  "Person1": $n1,
  "Person2": $n2
};
